SELECT ID, SESSION_ID, PROJECT_ID, PROJECT_FILE_ID, FILE_SHA256, PARSE_RESULT_ID, PARSE_VERSION, CANONICAL_TEXT_SHA256, EFFECTIVE_ROLE, ROLE_DECISION_ID, IDENTITY_DECISION_ID, SLOT_KEY, ORDINAL_NO, ACTIVE_FLAG, BOUND_BY, BOUND_AT, SELECTION_VERSION, VERSION_NO
